//! Normative AV2 Quantizer, Quantizer Matrices (`Quantizer_Matrix`, `Qm_Offset`), & Rate-Distortion
//! Optimized Quantization (`RDOQ`).
//!
//! Implements the normative AV2 base quantizer lookup (`DQ_LOOKUP`), the normative 15-level
//! quantization matrices (`FUNDAMENTAL_QM` & `QmTables` derived per AV2 Spec v1.0.0 §9.4.2–9.4.3
//! from `attachments/quantizer_matrix.h` and `attachments/qm_offset.h`), fast deadzone quantization
//! (`quantize_dequantize_block`), and Lagrangian rate-distortion optimized quantization (`quantize_rdoq_block`).

use crate::av2::headers::{FrameHeader, MAX_SEGMENTS};
use crate::av2::intops::{iclip, imax};
use crate::av2::levels::N_RECT_TX_SIZES;
use crate::av2::scan::SCANS;
use crate::av2::tables::TXFM_DIMENSIONS;

/// Returns the AV2 dequantizer step for quantizer index `qidx` (clamped to `0..=255`).
#[inline]
pub fn dq_lookup(qidx: i32) -> i32 {
    // Dequantisation lookup used by the reference decoder (dav2d):
    // QIDX 0 is lossless (step 64 in this fixed-point domain); all other
    // indices select one of 24 base steps scaled by 2^(qidx / 24).
    let qidx = qidx.clamp(0, 255);
    if qidx == 0 {
        return 64;
    }
    static DQ_LOOKUP_TBL: [u8; 24] = [
        40, 41, 43, 44, 45, 47, 48, 49, 51, 52, 54, 55, 57, 59, 60, 62, 64, 66, 68, 70, 72, 74, 76,
        78,
    ];
    let qidx = qidx - 1;
    let shift = qidx / 24;
    let idx = (qidx % 24) as usize;
    (DQ_LOOKUP_TBL[idx] as i32) << shift
}

