/// Normative `Qm_Offset[25]` from `attachments/qm_offset.h`.
pub static QM_OFFSET: [u16; 25] = [
    0, 16, 80, 336, 336, 1360, 1392, 1424, 1552, 1680, 2192, 336, 336, 2704, 2768, 2832, 3088,
    1680, 2192, 3344, 3472, 2832, 3088, 3344, 3472,
];

/// Derives the normative AV2 quantization matrix of size `tw * th` (`tw, th <= 32`) for
/// QM level `level` (`0..15`), `plane_type` (`0` = Luma, `1` = Chroma), and transform size `tx`
/// using the exact subsampling formula in AV2 Specification v1.0.0 §9.4.2:
/// ```text
/// ratioW = fW / tw, ratioH = fH / th
/// phaseW = (ratioW + 1) / 2 - 1, phaseH = (ratioH + 1) / 2 - 1
/// derivedMatrix[i * tw + j] = fundamentalMatrix[(ratioH * i + phaseH) * fW + ratioW * j + phaseW]
/// ```
pub fn derive_normative_qm(level: usize, plane_type: usize, tx: usize) -> Vec<u8> {
    let t_dim = &TXFM_DIMENSIONS[tx.min(N_RECT_TX_SIZES - 1)];
    let tw = (t_dim.w as usize * 4).min(32);
    let th = (t_dim.h as usize * 4).min(32);
    if level >= 15 {
        return vec![32u8; tw * th];
    }
    let fund = &FUNDAMENTAL_QM[level][plane_type.min(1)];
    let (fm, fw, fh) = if tw == th {
        (&fund[0..1024], 32usize, 32usize)
    } else if tw > th {
        (&fund[1536..2048], 32usize, 16usize)
    } else {
        (&fund[1024..1536], 16usize, 32usize)
    };
    let ratio_w = fw / tw.max(1);
    let ratio_h = fh / th.max(1);
    let phase_w = ratio_w.div_ceil(2) - 1;
    let phase_h = ratio_h.div_ceil(2) - 1;
    let mut out = vec![32u8; tw * th];
    // Store in column-major layout (c * th + r) to match `av2`'s transform block indexing
    for r in 0..th {
        for c in 0..tw {
            let val = fm[(ratio_h * r + phase_h) * fw + ratio_w * c + phase_w];
            out[c * th + r] = val;
        }
    }
    out
}

/// Frequency-dependent quantization weighting matrices (`AV2 Spec v1.0.0 §7.14.4 & §9.4`).
pub struct QmTables {
    pub qm: [[Vec<u8>; N_RECT_TX_SIZES]; 2],
}

impl Default for QmTables {
    fn default() -> Self {
        Self::new()
    }
}

impl QmTables {
    /// Initializes normative AV2 quantization matrices for QM level `4` across all 25 transform sizes.
    pub fn new() -> Self {
        Self::for_level(4)
    }

    /// Initializes normative AV2 quantization matrices for `level` (`0..=14`, or `>= 15` for flat `32`)
    /// across all 25 transform sizes.
    pub fn for_level(level: usize) -> Self {
        let mut qm: [[Vec<u8>; N_RECT_TX_SIZES]; 2] = [
            std::array::from_fn(|_| Vec::new()),
            std::array::from_fn(|_| Vec::new()),
        ];
        for tx in 0..N_RECT_TX_SIZES {
            qm[0][tx] = derive_normative_qm(level, 0, tx);
            qm[1][tx] = derive_normative_qm(level, 1, tx);
        }
        Self { qm }
    }
}

/// Initializes per-segment, per-plane `[dc, ac]` dequantization multipliers for a frame.
pub fn init_quant_tables(
    frame_hdr: &FrameHeader,
    qidx: i32,
    dq: &mut [[[u32; 2]; 3]; MAX_SEGMENTS],
) {
    let n = if frame_hdr.segmentation.enabled != 0 {
        MAX_SEGMENTS
    } else {
        1
    };
    for i in 0..n {
        let yac = if frame_hdr.segmentation.enabled != 0 {
            iclip(qidx + frame_hdr.segmentation.d.delta_q[i] as i32, 0, 255)
        } else {
            iclip(qidx, 0, 255)
        };
        let ydc = yac + frame_hdr.quant.ydc_delta as i32;
        let uac = yac + frame_hdr.quant.uac_delta as i32;
        let udc = yac + frame_hdr.quant.udc_delta as i32;
        let vac = yac + frame_hdr.quant.vac_delta as i32;
        let vdc = yac + frame_hdr.quant.vdc_delta as i32;

        dq[i][0][0] = dq_lookup(ydc) as u32;
        dq[i][0][1] = dq_lookup(yac) as u32;
        dq[i][1][0] = dq_lookup(udc) as u32;
        dq[i][1][1] = dq_lookup(uac) as u32;
        dq[i][2][0] = dq_lookup(vdc) as u32;
        dq[i][2][1] = dq_lookup(vac) as u32;
    }
}

/// Computes the effective scaled dequantizer multiplier `scaled_dq` (prior to `>> dq_shift`)
/// at scan position `pos` (`0` = DC, `>0` = AC), per AV2 Spec v1.0.0 §7.12.3.
#[inline]
fn effective_scaled_dq(pos: usize, rc: usize, dq_tbl: [u32; 2], qm: Option<&[u8]>) -> i64 {
    let is_ac = (pos != 0) as usize;
    let base_dq = dq_tbl[is_ac] as i64;
    if let Some(qm_slice) = qm {
        let qm_val = qm_slice.get(rc).copied().unwrap_or(32) as i64;
        (base_dq * qm_val + 16) >> 5
    } else {
        base_dq
    }
    .max(1)
}

/// Reconstructs the normative dequantized coefficient from signed quantized level `q_level`.
#[inline]
fn reconstruct_dq_coef(
    q_level: i32,
    pos: usize,
    rc: usize,
    dq_tbl: [u32; 2],
    qm: Option<&[u8]>,
    dq_shift: i32,
    cf_max: i32,
    lossless: bool,
) -> i32 {
    if q_level == 0 {
        return 0;
    }
    if lossless {
        return iclip(q_level, -cf_max - 1, cf_max);
    }
    let sign = if q_level < 0 { -1i64 } else { 1i64 };
    let abs_q = (q_level as i64).abs();
    let is_ac = (pos != 0) as usize;
    let base_dq = dq_tbl[is_ac] as i64;
    let dq_prod = if let Some(qm_slice) = qm {
        let qm_val = qm_slice.get(rc).copied().unwrap_or(32) as i64;
        ((base_dq * qm_val + 16) >> 5) * abs_q
    } else {
        base_dq * abs_q
    };
    let dq_val = ((dq_prod & 0xFFFFFF) + 4) >> dq_shift;
    iclip((sign * dq_val) as i32, -cf_max - 1, cf_max)
}

/// Reconstructs one dequantized coefficient from a decoded quantized level.
///
/// Mirrors the dequantization step of [`quantize_dequantize_block`] so the
/// decoder and the encoder reconstruction produce identical samples.
#[allow(clippy::too_many_arguments)]
pub fn dequantize_coef(
    q_level: i32,
    pos: usize,
    rc: usize,
    dq_tbl: [u32; 2],
    qm: Option<&[u8]>,
    tx_ctx: u8,
    bitdepth: u8,
    lossless: bool,
) -> i32 {
    let dq_shift = 3 + imax(0, tx_ctx as i32 - 2);
    let cf_max = !((!127u32) << bitdepth) as i32;
    reconstruct_dq_coef(q_level, pos, rc, dq_tbl, qm, dq_shift, cf_max, lossless)
}

/// Forward quantizes transformed coefficients `cf_in` into signed integer token levels `q_out`
/// and simultaneously computes the exact dequantized reconstruction coefficients `dq_out`.
///
/// Returns `eob` (the index in scan order of the last non-zero coefficient, or `-1` if all zero).
#[allow(clippy::too_many_arguments)]
pub fn quantize_dequantize_block(
    cf_in: &[i32],
    q_out: &mut [i32],
    dq_out: &mut [i32],
    tx: usize,
    dq_tbl: [u32; 2],
    qm: Option<&[u8]>,
    bitdepth: u8,
    is_intra: bool,
    lossless: bool,
) -> i32 {
    let t_dim = &TXFM_DIMENSIONS[tx];
    let sw = (t_dim.w as usize * 4).min(32);
    let sh = (t_dim.h as usize * 4).min(32);
    let n_coeffs = sw * sh;
    let scan = SCANS[tx];
    let dq_shift = 3 + imax(0, t_dim.ctx as i32 - 2);
    let cf_max = !((!127u32) << bitdepth) as i32;

    q_out[..n_coeffs].fill(0);
    dq_out[..n_coeffs].fill(0);

    let mut eob: i32 = -1;

    for i in 0..n_coeffs {
        let rc = scan[i] as usize;
        let c = cf_in[rc];
        if c == 0 {
            continue;
        }
        let sign = if c < 0 { -1i32 } else { 1i32 };
        let abs_c = (c as i64).abs();
        let abs_q = if lossless {
            abs_c.min(cf_max as i64) as i32
        } else {
            // Invert normative dequantization `((scaled_dq * abs_q) & 0xFFFFFF + 4) >> dq_shift`
            // (AV2 Spec v1.0.0 §7.12.3) in the pre-shifted domain so low-QP steps where
            // `scaled_dq < (1 << dq_shift)` or `scaled_dq` is not a multiple of `1 << dq_shift`
            // are not truncated, and clamp `abs_q` so `scaled_dq * abs_q` cannot wrap 24 bits.
            let rounding_num: i64 = if i == 0 {
                if is_intra { 11 } else { 9 }
            } else if is_intra {
                10
            } else {
                8
            };
            let scaled_dq = effective_scaled_dq(i, rc, dq_tbl, qm);
            let bias = (scaled_dq * rounding_num) >> 5;
            let q_max_24b = 0xFF_FFFFi64 / scaled_dq;
            let q_max_cf = (((cf_max as i64) << dq_shift) / scaled_dq).max(1);
            let q_limit = (cf_max as i64).min(q_max_24b).min(q_max_cf);
            (((abs_c << dq_shift) + bias) / scaled_dq).min(q_limit) as i32
        };
        if abs_q != 0 {
            let q_level = sign * abs_q;
            q_out[rc] = q_level;
            dq_out[rc] =
                reconstruct_dq_coef(q_level, i, rc, dq_tbl, qm, dq_shift, cf_max, lossless);
            eob = i as i32;
        }
    }

    // Backward EOB pruning: drop isolated trailing `|q| == 1` AC coefficients separated by a zero
    // run (`gap >= 2`) when their pre-quantized magnitude is below `1.0 * q_step`.
    if !lossless {
        while eob > 0 {
            let idx = eob as usize;
            let rc = scan[idx] as usize;
            if q_out[rc].abs() != 1 {
                break;
            }
            let mut prev_nz = eob - 1;
            while prev_nz >= 0 && q_out[scan[prev_nz as usize] as usize] == 0 {
                prev_nz -= 1;
            }
            let gap = (eob - prev_nz) as i64;
            if gap < 2 {
                break;
            }
            let scaled_dq = effective_scaled_dq(idx, rc, dq_tbl, qm);
            let abs_c_shifted = (cf_in[rc] as i64).abs() << dq_shift;
            let thresh_num = (23 + gap.min(9)).min(32);
            let min_c_shifted = (scaled_dq * thresh_num) >> 5;
            if abs_c_shifted < min_c_shifted {
                q_out[rc] = 0;
                dq_out[rc] = 0;
                eob = prev_nz;
            } else {
                break;
            }
        }
    }

    eob
}

/// Wave 2 Rate-Distortion Optimized Quantization (`RDOQ`):
/// Evaluates candidate quantized levels `q in {0, abs_q - 1, abs_q}` at each scan position and
/// performs backward EOB pruning using Lagrangian cost $J = \Delta D + \lambda_{\text{rdoq}} \cdot \Delta R$.
#[allow(clippy::too_many_arguments)]
pub fn quantize_rdoq_block(
    cf_in: &[i32],
    q_out: &mut [i32],
    dq_out: &mut [i32],
    tx: usize,
    dq_tbl: [u32; 2],
    qm: Option<&[u8]>,
    bitdepth: u8,
    is_intra: bool,
    lossless: bool,
    lambda_q8: u64,
) -> i32 {
    if lossless {
        return quantize_dequantize_block(
            cf_in, q_out, dq_out, tx, dq_tbl, qm, bitdepth, is_intra, true,
        );
    }

    let t_dim = &TXFM_DIMENSIONS[tx];
    let sw = (t_dim.w as usize * 4).min(32);
    let sh = (t_dim.h as usize * 4).min(32);
    let n_coeffs = sw * sh;
    let scan = SCANS[tx];
    let dq_shift = 3 + imax(0, t_dim.ctx as i32 - 2);
    let cf_max = !((!127u32) << bitdepth) as i32;

    q_out[..n_coeffs].fill(0);
    dq_out[..n_coeffs].fill(0);

    let rounding_num: i64 = if is_intra { 13 } else { 11 };
    let mut eob: i32 = -1;

    for i in 0..n_coeffs {
        let rc = scan[i] as usize;
        let c = cf_in[rc];
        if c == 0 {
            continue;
        }

        let scaled_dq = effective_scaled_dq(i, rc, dq_tbl, qm);
        let sign = if c < 0 { -1i32 } else { 1i32 };
        let abs_c = (c as i64).abs();
        let bias = (scaled_dq * rounding_num) >> 5;
        let q_max_24b = 0xFF_FFFFi64 / scaled_dq;
        let q_max_cf = (((cf_max as i64) << dq_shift) / scaled_dq).max(1);
        let q_limit = (cf_max as i64).min(q_max_24b).min(q_max_cf);
        let max_q = (((abs_c << dq_shift) + bias) / scaled_dq).min(q_limit) as i32;
        if max_q == 0 {
            continue;
        }

        let token_bits_q8 = |lvl: i32| -> u64 {
            let a = lvl.unsigned_abs() as u64;
            if a == 0 {
                96
            } else if a == 1 {
                560
            } else if a <= 4 {
                560 + (a - 1) * 320
            } else {
                1520 + (32 - (a as u32).leading_zeros() as u64) * 512
            }
        };

        let tx_scale = ((scaled_dq * scaled_dq) >> (2 * dq_shift)).max(1) as u64;
        let eff_lambda = (lambda_q8 * tx_scale) >> 11;

        let mut best_q = 0i32;
        let mut best_dq = 0i32;
        let dist0 = (c as i64 * c as i64) as u64;
        let mut best_cost = dist0 + ((eff_lambda * token_bits_q8(0)) >> 8);

        for cand_abs in [max_q - 1, max_q] {
            if cand_abs <= 0 {
                continue;
            }
            let cand_q = sign * cand_abs;
            let cand_dq = reconstruct_dq_coef(cand_q, i, rc, dq_tbl, qm, dq_shift, cf_max, false);
            let err = (c - cand_dq) as i64;
            let dist = (err * err) as u64;
            let cost = dist + ((eff_lambda * token_bits_q8(cand_q)) >> 8);
            if cost <= best_cost {
                best_cost = cost;
                best_q = cand_q;
                best_dq = cand_dq;
            }
        }

        if best_q != 0 {
            q_out[rc] = best_q;
            dq_out[rc] = best_dq;
            eob = i as i32;
        }
    }

    // Backward EOB pruning
    while eob > 0 {
        let idx = eob as usize;
        let rc = scan[idx] as usize;
        let q_val = q_out[rc];
        if q_val.abs() != 1 {
            break;
        }
        let c = cf_in[rc] as i64;
        let dq_val = dq_out[rc] as i64;
        let err_nz = c - dq_val;
        let dist_saving = (c * c - err_nz * err_nz).max(0) as u64;
        let scaled_dq = effective_scaled_dq(idx, rc, dq_tbl, qm);
        let q_step_sq = ((scaled_dq * scaled_dq) >> (2 * dq_shift)).max(1) as u64;
        let eff_lambda = (lambda_q8 * q_step_sq) >> 11;
        let eob_overhead_cost = (eff_lambda * 640) >> 8;
        if dist_saving < eob_overhead_cost {
            q_out[rc] = 0;
            dq_out[rc] = 0;
            eob -= 1;
            while eob >= 0 && q_out[scan[eob as usize] as usize] == 0 {
                eob -= 1;
            }
        } else {
            break;
        }
    }

    eob
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normative_qm_4x4_matches_spec() {
        let qm0 = QmTables::for_level(0);
        // In quantizer_matrix.h level 0 Luma 4x4:
        // 32, 43, 73, 97, 43, 67, 94, 110, 73, 94, 137, 150, 97, 110, 150, 200
        assert_eq!(qm0.qm[0][0][0], 32);
        assert_eq!(qm0.qm[0][0][15], 200);
    }

    #[test]
    fn test_lossless_quantize_is_identity() {
        let mut cf_in = [0i32; 16];
        cf_in[0] = 123;
        cf_in[5] = -45;
        let mut q_out = [0i32; 16];
        let mut dq_out = [0i32; 16];
        let eob = quantize_dequantize_block(
            &cf_in,
            &mut q_out,
            &mut dq_out,
            0,
            [4, 4],
            None,
            8,
            true,
            true,
        );
        assert!(eob >= 0);
        assert_eq!(dq_out[0], 123);
        assert_eq!(dq_out[5], -45);
    }
}
